  cv_edit_reset_confirm: { tr:'Tüm CV düzenlemeleriniz silinecek. Havuzdaki orijinal CV etkilenmez.', en:'All your CV edits will be removed. The original CV in the pool is unchanged.', ru:'Все ваши правки будут удалены. Оригинальное резюме в пуле не изменится.', kk:'Барлық өңдеулер жойылады. Қордағы түпнұсқа CV өзгермейді.', ky:'Бардык түзөтүүлөр өчүрүлөт. Бассейндеги оригинал CV өзгөрбөйт.', uz:'Barcha tahrirlaringiz o‘chiriladi. Havzadagi asl CV o‘zgarmaydi.', tk:'CV üýtgetmeleriňiziň hemmesi pozular. Hawaçyndaky asyl CV üýtgemeýär.', de:'Alle Ihre CV-Änderungen werden entfernt. Das Original im Pool bleibt unverändert.', th:'การแก้ไข CV ทั้งหมดจะถูกลบ เรซูเม่ต้นฉบับในพูลไม่เปลี่ยน', fa:'همه ویرایش‌های شما حذف می‌شود. رزومه اصلی در استخر تغییر نمی‌کند.' },
  pdf_free: { tr:'Ücretsiz indir', en:'Free download', ru:'Скачать бесплатно', kk:'Тегін жүктеу', de:'Kostenlos herunterladen', th:'ดาวน์โหลดฟรี', uz:'Bepul yuklab olish', fa:'دانلود رایگان', ky:'Акысыз жүктөө', tk:'Mugt göçürip almak' },
  pdf_nologo: { tr:'İndir (1 $)', en:'Download (1 $)', ru:'Скачать (1 $)', kk:'Жүктеу (1 $)', de:'Herunterladen (1 $)', th:'ดาวน์โหลด (1 $)', uz:'Yuklab olish (1 $)', fa:'دانلود (۱ دلار)', ky:'Жүктөө (1 $)', tk:'Göçürip almak (1 $)' },
  pdf_choose: { tr:'İndirme seçeneğini seç', en:'Choose a download option', ru:'Выберите вариант загрузки', kk:'Жүктеу нұсқасын таңдаңыз', de:'Download-Option wählen', th:'เลือกตัวเลือกการดาวน์โหลด', uz:'Yuklab olish variantini tanlang', fa:'یک گزینه دانلود را انتخاب کنید', ky:'Жүктөө вариантын тандаңыз', tk:'Göçürip almak görnüşini saýlaň' },
